UPDATE outbox_event SET status='PUBLISHING',attempt_count=attempt_count+1,
  locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE'
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PENDING' AND attempt_count=#{attemptCount}
  AND attempt_count<#{max_attempts} AND lock_version=#{lockVersion} AND next_attempt_at<=#{now}


UPDATE outbox_event SET attempt_count=attempt_count+1,locked_by=#{token},locked_at=#{now},
  lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE'
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount}
  AND attempt_count<#{max_attempts} AND locked_by=#{lockedBy} AND lock_version=#{lockVersion} AND locked_at<=#{cutoff}


UPDATE outbox_event SET status='PUBLISHING',locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,
  updated_at=#{now},updated_by_type='SERVICE' WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PENDING'
  AND attempt_count=8 AND lock_version=#{lockVersion} AND next_attempt_at<=#{now}


UPDATE outbox_event SET locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,
  updated_at=#{now},updated_by_type='SERVICE' WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING'
  AND attempt_count=8 AND locked_by=#{lockedBy} AND lock_version=#{lockVersion} AND locked_at<=#{cutoff}

