UPDATE outbox_event SET status='PUBLISHED',locked_by=NULL,locked_at=NULL,last_error_code=NULL,
  broker_confirmed_at=#{now},lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE'
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount}
  AND locked_by=#{token} AND lock_version=#{lockVersion} AND locked_at>#{cutoff}


UPDATE outbox_event SET status='PENDING',next_attempt_at=#{next},locked_by=NULL,locked_at=NULL,
  last_error_code=#{code},broker_confirmed_at=NULL,lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE'
WHERE tenant_id=#{tenantId} AND outbox_id=#{outboxId} AND status='PUBLISHING' AND attempt_count=#{attemptCount}
  AND locked_by=#{token} AND lock_version=#{lockVersion} AND locked_at>#{cutoff}
